style.css:
@-moz-document domain("ozon.ru"), domain("www.ozon.ru") {
/* ============================================================
     Ozon ships a full design-token system on :root — light
     tokens (--ozTextPrimary, --ozBGSecondary, --ozGray*, --ozWhite*
     …) drive most surfaces and text. It even carries a complete
     parallel dark set (--ozdt*), but never activates it when
     logged out. We retheme by remapping the LIGHT tokens to dark
     values, then patch the surfaces Ozon hardcodes to literal
     white (#fff) outside the token system: the header, product
     tiles (.tile-root), the footer, the PDP gallery stage and
     thumbnails, and every floating/sticky bar + dropdown.

     Selectors target stable [data-widget="…"] attributes and the
     structural .tile-root / typography (tsBody*, tsHeadline*)
     class families — NEVER content-hashed classes (.gq4_20 …),
     which rot on every build.

     Brand accents kept recognisable but tuned for dark:
       Ozon blue   #005bff -> #2e78ff (links/CTA on near-black)
       sale red    #f91155 -> #ff3c75
       positive    #10c44c (green, kept)
       rating gold #ffb800 (kept)
     ============================================================ */

  :root {
    color-scheme: dark;

    /* ---- our dark palette ---- */
    --d-bg: #14181d;          /* base canvas */
    --d-surface: #1c2128;     /* elevated cards / panels */
    --d-surface-2: #1a1f26;   /* secondary surface */
    --d-header: #0d1117;      /* header / footer / sticky bars */
    --d-border: #2a313a;      /* subtle border */
    --d-border-2: #353d47;    /* stronger border */
    --d-text: #e6edf3;        /* primary text */
    --d-text-2: #c4cdd6;      /* body text */
    --d-text-3: #9aa6b2;      /* muted / secondary */
    --d-text-4: #7d8893;      /* quaternary / hints */
    --d-blue: #2e78ff;        /* refined Ozon blue */
    --d-blue-hover: #5b96ff;
    --d-red: #ff3c75;         /* refined sale red */
    --d-green: #19c560;       /* positive */
    --d-gold: #ffc93c;        /* rating */

    /* ---- remap Ozon light text tokens -> light-on-dark ---- */
    --ozTextPrimary: var(--d-text) !important;
    --ozBlack: var(--d-text) !important;
    --ozCtrlNeutral: var(--d-text) !important;
    --ozTextSecondary: var(--d-text-3) !important;
    --ozTextTertiary: var(--d-text-2) !important;
    --ozTextQuaternary: var(--d-text-4) !important;
    /* "text on an inverse/brand ground" — must stay pure white, not our
       off-white text colour: it labels white-on-blue buttons and chips,
       where every point of contrast counts. */
    --ozTextPrimaryNegative: #ffffff !important;

    /* ---- remap Ozon light background tokens -> dark ---- */
    --ozBGPrimary: var(--d-bg) !important;
    --ozBGSecondary: var(--d-surface) !important;
    --ozBGTertiary: var(--d-surface-2) !important;
    --ozBGQuaternary: #2b333d !important;
    --ozBGPrimaryInverse: var(--d-surface) !important;
    --ozBGSecondaryInverse: var(--d-surface) !important;
    --ozBGPrimaryHover: #232a32 !important;
    --ozWhite: var(--d-surface) !important;
    --ozWhite1: var(--d-surface) !important;
    --ozWhite2: var(--d-surface-2) !important;

    /* ---- "Floor" / layer surface system (Ozon's elevation tokens,
       separate from --oz*; drive grid, cards, badges, panels) ---- */
    --layerFloor0: var(--d-bg) !important;       /* page floor */
    --layerFloor1: var(--d-surface) !important;  /* cards */
    --layerFloor2: var(--d-surface) !important;  /* nested */
    --layerFloor3: var(--d-surface-2) !important;
    --layerActiveFloor0: #232a32 !important;
    --layerActiveFloor1: #2b333d !important;
    --layerActiveFloor2: #2b333d !important;
    --layerActiveFloor3: #2b333d !important;
    --layerSurface: rgba(255, 255, 255, 0.04) !important;
    --layerActiveSurface: rgba(255, 255, 255, 0.1) !important;
    --layerCeil0: var(--d-surface) !important;
    --layerCeil1: var(--d-surface) !important;
    --layerOverlayParanja: rgba(255, 255, 255, 0.05) !important;
    --layerOverlayDimming: rgba(3, 8, 13, 0.6) !important;

    /* ---- grey scale: light end -> dark surfaces, dark end -> light text ---- */
    --ozGray90: #232a32 !important;
    --ozGray80: #2b333d !important;
    --ozGray70: var(--d-text-4) !important;
    --ozGray60: var(--d-text-3) !important;
    --ozGray40: var(--d-text-2) !important;
    --ozGray30: var(--d-text) !important;
    --ozGray20: var(--d-text) !important;

    /* ---- separators / dimming ---- */
    --ozSeparator: rgba(160, 175, 195, 0.16) !important;
    --ozSeparatorDark: rgba(160, 175, 195, 0.22) !important;
    --ozShadowSpread: rgba(0, 0, 0, 0.55) !important;
    --ozParandja: rgba(255, 255, 255, 0.04) !important;
    --ozParandjaHover: rgba(255, 255, 255, 0.08) !important;
    --ozCtrlNeutralPale: rgba(255, 255, 255, 0.05) !important;
    --ozHoverNeutralPale: rgba(255, 255, 255, 0.09) !important;
    --ozHoverNeutral: #e4e9f0 !important;
    --ozWhiteOverlay: rgba(20, 24, 29, 0.82) !important;
    --ozWhiteOverlay2: rgba(20, 24, 29, 0.62) !important;
    --ozWhiteOverlay3: rgba(20, 24, 29, 0.42) !important;

    /* ---- accents: keep brand identity, tune for dark ---- */
    --ozCtrlPrimary: var(--d-blue) !important;
    --ozAccentPrimary: var(--d-blue) !important;
    --ozTextAction: var(--d-blue) !important;
    --ozHoverPrimary: var(--d-blue-hover) !important;
    --ozAccentPrimaryHover: var(--d-blue-hover) !important;
    --ozBlue: var(--d-blue) !important;
    --ozBlueHover: var(--d-blue-hover) !important;
    --ozCtrlSale: var(--d-red) !important;
    --ozTextSale: var(--d-red) !important;
    --ozAccentAlert: var(--d-red) !important;
    --ozRed: var(--d-red) !important;
    --ozCtrlPositive: var(--d-green) !important;
    --ozTextPositive: var(--d-green) !important;
    --ozAccentSecondary: var(--d-green) !important;
    --ozGreenUi: var(--d-green) !important;
    --ozRating: var(--d-gold) !important;
    --ozYellowBrand: var(--d-gold) !important;
    --ozTextWarning: var(--d-gold) !important;

    /* ============================================================
       MODERN SEMANTIC TOKEN LAYER (--text* / --graphic* / --bg*).
       Ozon migrated off the legacy --oz* names: nearly every colour
       on the site now resolves through this layer (the "hardcoded
       rgb(7,7,7)" text is simply --textPrimary: #070707). Remapping
       it here is what lets us DELETE the blanket typography rules
       that used to force one colour on whole widgets and flattened
       the site's semantics — the sale pink, the Ozon-card green, the
       Ozon-fresh teal, link vs heading, active vs idle.

       Rules of the remap:
         * neutral dark text/icon tokens -> our light text scale
         * saturated brand tokens are KEPT, only lifted where they
           fail contrast on near-black (blue #005bff -> #2e78ff …)
         * "…Dynamic" / "…Inverted" / "…OnDark" tokens are ALREADY
           light (they paint on dark/brand grounds) -> untouched
         * saturated brand FILLS (--bgAccentPrimary pink pill,
           --bgOzonPrimary blue CTA, lime/gold promo fills) -> untouched
       ============================================================ */

    /* -- neutral text: dark -> light -- */
    --textPrimary: var(--d-text) !important;
    --textPremium: var(--d-text) !important;
    --textActivePremium: var(--d-text) !important;
    --textDarkKey: var(--d-text) !important;
    --textSecondary: var(--d-text-3) !important;
    --textTertiary: var(--d-text-4) !important;
    --textOxford: var(--d-text-3) !important;

    /* -- neutral icon/glyph ("graphic"): dark -> light -- */
    --graphicPrimary: var(--d-text) !important;
    --graphicKey: var(--d-text) !important;
    --graphicDarkKey: var(--d-text) !important;
    --graphicPremium: var(--d-text) !important;
    --graphicActivePremium: var(--d-text) !important;
    --graphicSecondary: var(--d-text-3) !important;
    --graphicTertiary: var(--d-text-4) !important;
    --graphicQuaternary: var(--d-text-4) !important;
    --graphicTabbarIconPrimary: var(--d-text) !important;
    --graphicTabbarIconSecondary: var(--d-text-4) !important;
    --graphicOxford: var(--d-text-3) !important;

    /* NOT remapped: the "…OnLight" pair (--textPrimaryOnLight,
       --graphicPrimaryOnLight, --textSecondaryOnLight, …). The suffix
       names the CONTEXT, not the role: these are the dark values a
       component uses when it paints itself on a light ground — and
       several use them as a BACKGROUND for a dark pill with
       --textLightKey white text (the home promo-counter chip does
       exactly this). Lifting them turned that chip into white-on-white. */

    /* -- brand accents: identity kept, lifted to clear contrast -- */
    --textAction: var(--d-blue) !important;
    --textOzon: var(--d-blue) !important;
    --textActiveAction: var(--d-blue-hover) !important;
    --textActiveOzon: var(--d-blue-hover) !important;
    --graphicActionPrimary: var(--d-blue) !important;
    --graphicActiveActionPrimary: var(--d-blue-hover) !important;
    --graphicActiveOzon: var(--d-blue-hover) !important;
    --graphicPremiumBlue: #4d8bff !important;
    --graphicActivePremiumBlue: #4d8bff !important;
    --textAccent: var(--d-red) !important;
    --textAccentOnLight: var(--d-red) !important;
    --textActiveAccent: #ff6d97 !important;
    --textExpress: var(--d-red) !important;
    --textActiveExpress: #ff6d97 !important;
    --textNegative: #ff6a45 !important;
    --textMarketing: #8a82f6 !important;
    --textActiveMarketing: #a49dff !important;
    --textGuarantee: #c46bff !important;
    --graphicGuarantee: #c46bff !important;

    /* -- neutral light surfaces: light -> dark -- */
    --bgPrimary: var(--d-bg) !important;
    --bgControl: var(--d-surface) !important;
    --bgPremiumPrimary: var(--d-surface) !important;
    --bgSecondary: rgba(255, 255, 255, 0.06) !important;
    --bgActivePrimary: #2b333d !important;
    --bgActivePremiumPrimary: #2b333d !important;
    --bgSelectInverted: var(--d-surface) !important;
    --bgActiveSelectInverted: #2b333d !important;
    --bgTabbarPrimary: var(--d-header) !important;
    --bgOverlap: rgba(20, 24, 29, 0.55) !important;

    /* -- pale tinted callout panels: keep the hue, invert the value -- */
    --bgOpaqueSecondary: #1f2630 !important;
    --bgOpaqueActionSecondary: #16233a !important;
    --bgOpaqueOzonSecondary: #16233a !important;
    --bgOpaqueAccentSecondary: #2e1622 !important;
    --bgOpaqueApparelSecondary: #2e1622 !important;
    --bgOpaquePositiveSecondary: #13291d !important;
    --bgOpaqueNegativeSecondary: #2e1a17 !important;
    --bgOpaqueWarningSecondary: #2b2415 !important;
    --bgOpaqueMarketingSecondary: #232042 !important;
    --bgOpaqueFreshSecondary: #12292a !important;
    --bgOpaqueEconomSecondary: #2b2318 !important;
    --bgAccentOnLight: #2e1622 !important;
    --bgApparelPiggy: #2e1622 !important;
    --bgPositiveOnLight: #13291d !important;
    --bgWarningOnLight: #2b2415 !important;
    --bgMarketingOnLight: #232042 !important;
    --bgMarketingSecondarySolid: #232042 !important;

    /* -- scroll-fade gradients that hardcode a white end stop -- */
    --grFadeHorizontalFloor1: linear-gradient(
      to right,
      rgba(28, 33, 40, 0) 0%,
      var(--d-surface) 40%
    ) !important;
    --grFavouritePromoFade: linear-gradient(
      to right,
      rgba(28, 33, 40, 0) 0%,
      var(--d-surface) 100%
    ) !important;
  }

  /* ============================================================
     BASE
     ============================================================ */
  html, body {
    background-color: var(--d-bg) !important;
    color: var(--d-text) !important;
  }

  /* soften every bright border to a subtle dark one */
  * {
    border-color: var(--d-border) !important;
  }

  /* ============================================================
     NOTE — there is deliberately NO global `ts*` typography colour
     rule here. Ozon's ts* classes carry font metrics only; the text
     colour comes from the --text and --graphic tokens remapped above.
     A blanket `[class*="tsBodyControl"] { color: … }` outranks those
     tokens (attribute selector beats the token's element rule) and
     flattened every semantic colour on the site at once: the sale
     pink −NN%, the white label on the pink "Распродажа" pill, the
     Ozon-card green price, the "Вход с Apple" white label, the
     "или" divider, and every action link. Colour text through the
     tokens; only patch what the tokens genuinely cannot reach.
     ============================================================ */

  /* ============================================================
     LITERAL-WHITE SURFACE NEUTRALISER
     Ozon hardcodes white on many wrappers outside the tokens
     (inline styles + the .search-bar-wrapper / wallpaper shells).
     Repaint white/near-white backgrounds to elevated dark.
     ============================================================ */
  [style*="background-color: rgb(255, 255, 255)"],
  [style*="background-color:#fff"],
  [style*="background-color: #fff"],
  [style*="background: rgb(255, 255, 255)"],
  [style*="background:#fff"],
  [style*="background-color: rgb(245, 247, 250)"],
  [style*="background-color:#f5f7fa"],
  [style*="background-color: #f5f7fa"],
  .search-bar-wrapper,
  [data-widget="searchBarDesktop"] > div {
    background-color: var(--d-surface) !important;
  }
  [data-widget="wallpaper"] {
    background-color: var(--d-bg) !important;
  }
  /* the catalog ("Каталог") menu wraps its blue CTA button in a
     white shell; flatten the wrapper to the header colour but leave
     the blue button itself (a genuine brand CTA) untouched */
  [data-widget="catalogMenu"],
  [data-widget="catalogMenu"] > div {
    background-color: var(--d-header) !important;
    color: var(--d-text) !important;
  }
  [data-widget="searchBarDesktop"] div {
    background-color: transparent !important;
  }
  /* seasonal / promo container shells */
  [data-widget="seasonWidget"] {
    background-color: var(--d-bg) !important;
  }

  /* ------------------------------------------------------------
     CATALOG MEGA-MENU (Каталог flyout) — the full category panel is
     rendered through a Vue portal (.vue-portal-target) mounted at body
     level, OUTSIDE the catalogMenu widget, as a literal-WHITE panel
     (hashed uw_* class, no role/aria). The widget-scoped header rules
     never reach it, so on dark the whole category flyout opens stark
     white. It only mounts on click, so the page-load element-bg audit
     never sees it. Darken the portal panel to the base canvas; the
     category links keep the brand blue via the link rule, and headings
     are lifted to readable light below. ------------------------- */
  .vue-portal-target,
  .vue-portal-target > div {
    background-color: var(--d-bg) !important;
  }
  /* The flyout is a separate Vue bundle: it does NOT use the --text*
     tokens, it hardcodes literal colours (#070707 headings, navy
     rgba(0,26,51,.6) links, rgba(0,26,52,.2) rail glyphs, #005bff
     actions). So it needs explicit rules — but ones that PRESERVE the
     hierarchy. The old theme leaned on a global `a { color: blue }`,
     which painted all ~200 links AND the section headings the same
     blue, erasing heading-vs-link entirely. Colour by role instead:
     section headings + rail labels primary, category links secondary,
     "Еще" toggles and the loaded rail category action-blue. */
  .vue-portal-target a {
    color: var(--d-text-2) !important;
  }
  .vue-portal-target a[class*="tsBody500"],
  .vue-portal-target a[class*="tsBodyControl500"] {
    color: var(--d-text) !important;
  }
  .vue-portal-target a:hover {
    color: var(--d-blue) !important;
  }
  .vue-portal-target svg {
    color: var(--d-text-4) !important;
  }
  .vue-portal-target button,
  .vue-portal-target button span,
  .vue-portal-target button svg {
    color: var(--d-blue) !important;
  }
  .vue-portal-target a[isload="true"],
  .vue-portal-target a[isload="true"] svg {
    color: var(--d-blue) !important;
  }
  /* the currently-selected left-rail category paints a near-white pill
     (#f5f7fa via a hashed class, NOT a token) as its active highlight —
     a stark white box in the dark flyout. It only mounts on hover, so the
     page-load audit never sees it. It is uniquely the one loaded category
     (a[isload="true"]); repaint it to an elevated active dark surface so
     the highlight reads as a selection, not a white box. */
  .vue-portal-target a[isload="true"] {
    background-color: var(--layerActiveFloor0) !important;
  }

  /* ------------------------------------------------------------
     BODY-MOUNTED MODAL PORTALS — Ozon mounts marketing / auth popups
     (e.g. the "Покупайте на Ozon как юридическое лицо" B2B modal) into a
     body-level [mountto="body"] wrapper, NOT a role="dialog", so the
     floating-surface dialog rule never reaches them. Their content panel
     ships literal #fff via hashed uw_* DIVs; the panel's own text is
     already lifted to light by the token/typography remaps, so on the
     white panel it goes light-on-light (invisible), and the panel is a
     stark white box on dark. The modal only mounts on interaction, so the
     load-time element-bg audit never sees it. Darken the panel DIVs to the
     elevated surface — this leaves the blue CTA and the white close-X
     (both <button>, not div) untouched, and the top promo banner (an
     image) unaffected — so the modal reads as a dark panel and its light
     text becomes legible. ---------------------------------------- */
  [mountto="body"] div[class*="uw_"] {
    background-color: var(--d-surface) !important;
  }

  /* ============================================================
     HEADER / NAV (data-widget="header") + sub-bars
     ============================================================ */
  [data-widget="header"],
  [data-widget="header"] > div,
  [data-widget="catalogMenu"],
  [data-widget="horizontalMenu"],
  [data-widget="addressBookBarWeb"],
  [data-widget="selectedCurrencyLanguage"],
  [data-widget="tapTags"] {
    background-color: var(--d-header) !important;
    color: var(--d-text) !important;
  }
  /* STICKY / AFFIXED HEADER (appears on scroll): Ozon mounts a
     position:fixed clone of the header whose OWN background is
     transparent but which paints a full-size WHITE panel through a
     ::before pseudo-element (background:#fff). Neutralising element
     backgrounds never reaches it, so on scroll the bar shows stark
     white behind the logo and around the right-hand icon cluster
     (the centre stays dark only because catalogMenu/search paint
     their own opaque surfaces over it). Repaint the header pseudo
     panel to the header chrome colour so the whole affixed bar is
     dark and its (already light) icons read.

     SCOPED to the header's own grandchild rows. An unscoped
     `[data-widget="header"] div::before` reaches EVERY div
     pseudo inside the header — including the search-suggest flyout,
     which is mounted inside <header>. Each suggest product tile has a
     full-size ::after overlay layer, so the broad rule painted an
     opaque --d-header panel over every product photo in the suggest
     panel (thumbnails rendered as blank dark boxes). Only the affixed
     bar's own ::before is ever white, and it is a grandchild of the
     widget, so scope there. */
  [data-widget="header"]::before,
  [data-widget="header"]::after,
  [data-widget="header"] > div::before,
  [data-widget="header"] > div::after,
  [data-widget="header"] > div > div::before,
  [data-widget="header"] > div > div::after {
    background-color: var(--d-header) !important;
  }

  /* MAIN-NAV ROW (data-widget="horizontalMenu") — Ozon renders each
     item's colour as an INLINE style, server-driven per item: the
     ordinary entries get `color:rgba(0, 26, 51, 0.6)` (dark navy,
     invisible on our dark bar) while "Ozon fresh" gets its brand teal
     `color:#00a6a6`. An inline value beats any class rule, and a
     blanket `[data-widget="horizontalMenu"] a { color }` would erase
     the teal along with the navy.

     Match the navy inline value literally, so only those items lift.
     The glyphs then need `color: inherit` — Ozon paints them
     `fill: currentColor` but pins that currentColor with its OWN
     literal navy class rule, so they do not follow the item's colour
     on their own. Inheriting reaches "Для бизнеса" (a <button>, which
     every `… a svg` rule structurally missed, leaving its briefcase
     dark-on-dark) AND leaves the Ozon-fresh leaf teal, because it
     inherits that item's teal. No brand special-case needed. */
  [data-widget="horizontalMenu"] [style*="color:rgba(0, 26, 51, 0.6)"] {
    color: var(--d-text) !important;
  }
  [data-widget="horizontalMenu"] a svg,
  [data-widget="horizontalMenu"] a span,
  [data-widget="horizontalMenu"] button svg,
  [data-widget="horizontalMenu"] button span {
    color: inherit !important;
  }
  [data-widget="horizontalMenu"] a:hover,
  [data-widget="horizontalMenu"] button:hover {
    color: var(--d-blue-hover) !important;
  }

  /* ------------------------------------------------------------
     OZON FRESH category sub-nav (data-widget="horizontalCategoryMenu")
     — the horizontal category row on the Ozon Fresh landing page
     (ПРОДУКТЫ / ДЛЯ МАМ И ДЕТЕЙ / КРАСОТА И ЗДОРОВЬЕ / …). Ozon
     ships its wrapper as a literal WHITE bar (rgb(255,255,255)) with
     near-black label links (rgb(7,7,7)); it only appears on this
     Fresh variant, so the home/PDP audits missed it. Darken the bar
     to the elevated surface and lift the labels to readable light;
     hover/active brighten. ------------------------------------- */
  [data-widget="horizontalCategoryMenu"],
  [data-widget="horizontalCategoryMenu"] > div,
  [data-widget="horizontalCategoryMenu"] nav,
  [data-widget="horizontalCategoryMenu"] ul {
    background-color: var(--d-surface) !important;
    border-color: var(--d-border) !important;
  }
  [data-widget="horizontalCategoryMenu"] a,
  [data-widget="horizontalCategoryMenu"] li,
  [data-widget="horizontalCategoryMenu"] span {
    color: var(--d-text-2) !important;
  }
  [data-widget="horizontalCategoryMenu"] a:hover,
  [data-widget="horizontalCategoryMenu"] a:hover span,
  [data-widget="horizontalCategoryMenu"] li:hover,
  [data-widget="horizontalCategoryMenu"] a[aria-current],
  [data-widget="horizontalCategoryMenu"] a[aria-current] span {
    color: var(--d-text) !important;
  }

  /* CATALOG MEGA-MENU text: the flyout's section headings and its
     category links are BOTH <a>, and natively differ (headings are
     --textPrimary near-black, links are --textSecondary grey). The
     tokens colour them correctly; nothing to override. Only the
     heading weight distinguishes them, exactly as on the light site. */

  /* ============================================================
     SEARCH BAR + INPUT  (data-widget="searchBarDesktop")
     ============================================================ */
  [data-widget="searchBarDesktop"] {
    background-color: transparent !important;
  }
  [data-widget="searchBarDesktop"] input,
  input[type="text"],
  input[type="search"],
  textarea {
    background-color: var(--d-surface) !important;
    color: var(--d-text) !important;
    border-color: var(--d-border-2) !important;
  }
  [data-widget="searchBarDesktop"] input::placeholder,
  input::placeholder,
  textarea::placeholder {
    color: var(--d-text-3) !important;
    opacity: 1 !important;
  }
  /* autocomplete / suggest dropdown — must be opaque dark */
  [data-widget="searchBarDesktop"] ul,
  [data-widget="searchBarDesktop"] [role="listbox"] {
    background-color: var(--d-surface) !important;
    border-color: var(--d-border) !important;
  }
  /* SEARCH SUGGEST FLYOUT — Ozon renders the autocomplete/suggest
     panel from its search CSS module (.search_* classes) OUTSIDE the
     searchBarDesktop widget, with a TRANSPARENT background. On the
     light site that simply showed the white page behind it; on dark
     the panel lets colourful home banners / hero images bleed THROUGH
     the suggestion list (floating-surface bleed-through). The .search_
     prefix is the module name (stable across builds; only the hash
     suffix rotates). Give the flyout panel a solid opaque dark backing
     so the query suggestions + product previews read on every page.

     SCOPED to .search-bar-wrapper: an unscoped `div[class*="search_"]`
     also matched the flyout's full-viewport SCRIM (a position:fixed
     z-501 sibling that lives OUTSIDE the wrapper and is natively a
     translucent rgba(3,8,13,.32) dim). Painting that opaque blanked the
     whole page behind the suggest panel. The scrim keeps its own dim. */
  .search-bar-wrapper div[class*="search_"] {
    background-color: var(--d-bg) !important;
  }
  /* COUNTRY-CODE SELECTOR (OZON ID login modal — a same-origin
     www.ozon.ru/ozonid-lite iframe, so the theme applies inside it).
     The phone field's country picker renders the flag + dial code
     ("+7"/"+33") on a dark button, with a searchable dropdown driven by
     a role="combobox" name="filter" text input laid OVER the collapsed
     button to capture keystrokes. Our generic input background rule
     painted that overlay input opaque (--d-surface), covering the dial
     code so the box looked empty (the code text is light but hidden
     BEHIND the opaque overlay — an audit-blind overlapping-input miss;
     only elementsFromPoint reveals it). The main search input is
     name="text", so scoping to name="filter" avoids any collision.
     Make the overlay transparent so the dial code reads; typed filter
     text still shows light on the button's dark surface. */
  input[role="combobox"][name="filter"] {
    background-color: transparent !important;
  }

  /* ============================================================
     PRODUCT TILES / CARDS  (.tile-root, tileGridDesktop)
     ============================================================ */
  [data-widget="tileGridDesktop"],
  [data-widget="searchResultsV2"],
  [data-widget="skuGrid"],
  [data-widget="skuShelfGoods"] {
    background-color: transparent !important;
  }
  .tile-root,
  .tile-hover-target,
  [data-widget="tileGridDesktop"] .tile-root {
    background-color: var(--d-surface) !important;
    border-color: var(--d-border) !important;

    /* DISCOUNT pill + its scroll-fade. Ozon renders the "−NN%" badge
       with an INLINE `background: var(--bgLightKey)` and prepends a
       6px fade div carrying an inline
       `background: linear-gradient(to right, transparent, var(--bgLightKey))`
       that masks the strikethrough price as it scrolls under the badge.
       --bgLightKey is literal #fff, so on dark the badge sat on a white
       pill and the fade rendered as a bright bar across the price row.
       A `background-color: transparent` override cannot clear the fade
       (it is a background-IMAGE) — element-bg audits pass clean while
       the bar glares. Rebinding the token on the card makes BOTH the
       pill and its gradient resolve to the card surface, and leaves the
       pink --textAccent badge text reading on dark. */
    --bgLightKey: var(--d-surface) !important;
  }
  .tile-root span,
  .tile-root a,
  .tile-root div {
    border-color: var(--d-border) !important;
  }

  /* ============================================================
     CARD / PRODUCT TEXT — nothing to force here. Card text (title,
     rating, review count, "N шт осталось", brand, "Оригинал") is
     coloured by --textPrimary / --textSecondary / --textTertiary,
     and the semantic bits by --textAccent (pink −NN%),
     --textPositive (green Ozon-card price) and --grSale (the
     orange->magenta gradient-clipped sale price). All are remapped
     at :root, so they render light-on-dark WITH their meaning intact.

     The rules that used to live here forced .tile-root ts* text to
     one of two neutral greys. That flattened, on every card: the
     pink −NN%, the white label on the pink "Распродажа" pill and the
     violet "баллы за отзыв" pill, the Ozon-card green price, the blue
     "Ozon" seller mark, and the sale price's gradient — while every
     contrast threshold still passed, because grey on dark is legible.
     ============================================================ */

  /* ============================================================
     PRODUCT DETAIL PAGE (PDP)
     ============================================================ */
  /* PDP text (title, breadcrumbs, spec labels/values, SKU/share/compare,
     review lines) is coloured through --textPrimary/Secondary/Tertiary,
     remapped at :root — no per-widget text override needed. The blanket
     that used to sit here (`webPdpGrid span, div, p, li, h1…`) also
     erased the PDP's semantic colours: the green --textPositive
     Ozon-card price, the pink --textAccent discount, and the blue
     --textAction "Перейти в магазин" / seller links. */

  /* TITLE TRUNCATION FADE — when the product name is long enough to
     clip, Ozon appends a "…ещё" (show more) toggle whose wrapper paints
     a horizontal linear-gradient ::before that fades the last line of
     text into the page background (…transparent -> #fff). On the light
     site that blended into the white page; on dark it renders a stark
     WHITE smear across the end of the title. The gradient is a
     background-IMAGE with a transparent background-color, so the
     element-bg audit passes clean (it only mounts when the title is
     truncated, so short-title PDPs never show it). Remap the fade to the
     base canvas so it blends into the dark page instead of flashing
     white. Only one heading ::before ever carries a background-image (this
     fade), so scoping to the widget's pseudos is safe. */
  [data-widget="webProductHeading"] *::before {
    background-image: linear-gradient(
      90deg,
      rgba(20, 24, 29, 0),
      var(--d-bg) 57%
    ) !important;
  }

  /* PDP white delivery/seller panels: repaint the panel surface dark
     (they ship literal #fff via hashed classes). Restricted to DIVs:
     the "В корзину" primary CTA is a <button class="pdp_f1a">, and an
     element-agnostic `[class*="pdp_"]` neutraliser stripped its brand
     blue fill, leaving a white label floating on the page with no
     button behind it. A flattened CTA still passes every contrast
     check, so no scan reported it. */
  [data-widget="webPdpGrid"] div[class*="pdp_"] {
    background-color: transparent !important;
  }

  /* PDP title truncation "…ещё" pill (span.pdp_h5b) + its sibling rating
     background both ship `background: var(--graphicLightKey)` = literal #fff,
     so they render a WHITE box on the dark title. --graphicLightKey is NOT
     remapped at :root on purpose: it is a CONTEXT-named "light key" the site
     also uses as `color:`/`--icon-color`/`--loader-color` for WHITE text and
     glyphs on dark/coloured grounds (the .b5_7_0-a5 story labels, loaders,
     icons). A :root lift would flip all of those dark-on-dark. So rebind only
     the two BACKGROUND uses here to the page canvas — an opaque pill that
     masks the clamped text edge and blends seamlessly, matching the native
     white-on-white (invisible) pill. */
  span.pdp_h5b,
  .pdp_ar3 .pdp_r4a .pdp_ar5.pdp_a5r {
    background: var(--d-bg) !important;
  }

  /* MAIN CTA BUTTON (В корзину) — a genuine brand-coloured button; keep
     its label bright white on the blue fill. The secondary buttons
     (Купить сейчас / Оплатить позже) are NOT included: they ship a
     translucent-blue ground with blue --textAction label, and forcing
     white on them erased the primary/secondary distinction. */
  [data-widget="webAddToCart"] button,
  [data-widget="webAddToCart"] button span {
    color: #ffffff !important;
  }

  /* Review tiles (pinnedReview / webReviewGallery / bigPromoPDP) ship a
     white card surface; drop it so they sit on the page canvas. Their
     text is token-coloured and needs no override. */
  [data-widget="pinnedReview"],
  [data-widget="pinnedReview"] div,
  [data-widget="webReviewGallery"],
  [data-widget="webReviewGallery"] div,
  [data-widget="webReviewProductScore"] div,
  [data-widget="webReviewTabs"] div,
  [data-widget="bigPromoPDP"],
  [data-widget="bigPromoPDP"] div {
    background-color: transparent !important;
  }
  /* REVIEW RATING HISTOGRAM ("5 звёзд … 1 звезда" bars): the webReviewTabs
     `div { transparent }` reset above flattens BOTH the grey track and the gold
     proportion fill, so the distribution bars vanish (only the counts remain).
     Ratings are a kept-brand surface, so restore the gold fill. The fill is the
     only descendant carrying an inline PERCENT width (the track/underline use px),
     so this matches exactly the five bars and never the blue tab underline. */
  [data-widget="webReviewTabs"] div[style*="width"][style*="%"] {
    background-color: var(--d-gold) !important;
  }

  /* GALLERY: the stage + thumbnail tiles are white CONTAINERS
     behind/around the photo. Darken the container, not the <img>.
     pdp_* are hashed but the gallery is most reliably reached
     structurally via the widget; repaint any white wrapper inside. */
  [data-widget="webGallery"] {
    background-color: transparent !important;
  }
  [data-widget="webGallery"] div,
  [data-widget="webListPhotos"] div {
    background-color: transparent !important;
  }
  /* product photos sit on white in the source; give the photo
     frame a soft light mat so cut-out PNGs stay legible, but the
     surrounding stage/thumbnail strip stays dark */
  [data-widget="webGallery"] img,
  [data-widget="webListPhotos"] img,
  .tile-root img {
    background-color: #f3f5f8 !important;
    border-radius: 6px;
  }

  /* ============================================================
     FLOATING / STICKY SURFACES — must stay SOLID opaque dark so
     content doesn't bleed through on scroll. Covers sort bar,
     sticky buybox, sticky add-to-cart, modals, dropdowns, popovers.
     ============================================================ */
  /* SELECTED filter chips reuse Ozon's primary-button component:
     `background: var(--ozCtrlPrimary); color: var(--ozTextPrimaryNegative)`.
     --ozCtrlPrimary is dual-use (5 text rules, 2 fill rules), so it is
     globally lifted to our brighter blue for the TEXT cases — but on a
     FILL that lift drops the white chip label to 3.4:1. Rebind the token
     back to the native brand blue inside this fill-only widget: white on
     #005bff is 5.4:1, and the chip stays unmistakably Ozon-blue. */
  [data-widget="searchResultsFiltersActive"] {
    --ozCtrlPrimary: #005bff !important;
  }

  [data-widget="searchResultsSort"],
  [data-widget="searchResultsFiltersActive"],
  [data-widget="webStickyProducts"],
  [data-widget="stickyContainer"],
  [data-widget="webChatButton"],
  [class*="sticky"],
  [role="dialog"],
  [role="menu"],
  [role="listbox"],
  [role="tooltip"] {
    background-color: var(--d-header) !important;
    color: var(--d-text) !important;
    border-color: var(--d-border) !important;
  }
  /* ============================================================
     FILTERS / LEFT RAIL  (data-widget="filtersDesktop")
     audit all states: default label, hover, checked.
     ============================================================ */
  [data-widget="filtersDesktop"],
  [data-widget="filtersDesktop"] div {
    background-color: transparent !important;
  }
  /* The left-rail "Категория" / sort card paints its white panel through a
     full-size ::before pseudo-element on the <aside> wrapper (a hashed class,
     background:#fff), NOT on the element's own background — so neutralising the
     element backgrounds above leaves the card stark WHITE. Repaint every
     filter-rail pseudo layer to the elevated dark surface so the card reads as
     a panel instead of a bright box. */
  [data-widget="filtersDesktop"] *::before,
  [data-widget="filtersDesktop"] *::after {
    background-color: var(--d-surface) !important;
  }
  /* BRAND-LOGO CHECKBOXES (Xiaomi / Apple / Poco / … in the Бренд filter) render
     the logo as an <img> inside a checkbox box that carries a full-size,
     natively near-transparent ::after overlay. The rule above repaints that
     overlay to an OPAQUE elevated surface, which sat ON TOP of the logo and
     blanked every brand tile to an empty dark square (the logo bitmap still
     paints — canvas-samples orange for Xiaomi — it is simply covered). The
     ::after is a positioned pseudo, so lift the logo images into their own
     positive stacking layer to paint above it. Filter images are only these
     brand/store logos, which carry their own light ground, so no mat needed. */
  [data-widget="filtersDesktop"] img {
    position: relative !important;
    z-index: 1 !important;
  }
  /* Filter labels, category links and the "Посмотреть все" action row
     are token-coloured (--textPrimary / --textSecondary / --textAction);
     no override. The old blanket here greyed every rail link, and a
     `[class*="tsBodyControl500"] { color: blue }` companion then turned
     the whole category rail into a wall of blue links.

     HOVER is the exception: Ozon hardcodes the hovered link colour as a
     literal #0050e0 (16 rules, no token), which is its "pressed blue" —
     fine on the white site, but only ~2.6:1 on our near-black canvas, so
     hovering a link makes it HARDER to read. Lift the hover on the link
     surfaces we own. (A global `a:hover` is deliberately avoided: most
     Ozon anchors — tile titles above all — do not change colour on hover
     natively, and a blanket would invent a blue hover for them.) */
  [data-widget="filtersDesktop"] a:hover,
  [data-widget="filtersDesktop"] label:hover,
  [data-widget="breadCrumbs"] a:hover,
  [data-widget="footer"] a:hover {
    color: var(--d-blue-hover) !important;
  }

  /* ============================================================
     FOOTER
     ============================================================ */
  [data-widget="footer"],
  [data-widget="footer"] > div {
    background-color: var(--d-header) !important;
  }

  /* ============================================================
     CART  (logged-out cart renders the same widget shell)
     ============================================================ */
  [data-widget="cartList"],
  [data-widget="splitColumns"],
  [data-widget="splitItems"],
  [data-widget="cartFooter"],
  [data-widget="cartEmpty"] {
    background-color: transparent !important;
  }

  /* ============================================================
     LINKS / ACCENTS
     Ozon paints action text with --textAction (#005bff), which only
     reaches ~2.9:1 on the near-black base; the token remap lifts it to
     #2e78ff. There is deliberately NO blanket `a { color: blue }` rule:
     most Ozon anchors are NOT action-coloured (catalog flyout links are
     --textSecondary grey, its headings --textPrimary, filter-rail
     categories --textPrimary, tile titles --textPrimary), and painting
     every <a> blue turned the whole category mega-menu and filter rail
     into indistinguishable blue text with headings lost.
     ============================================================ */

  /* SCROLL-TO-TOP DISC (data-widget="homeButton") — a position:fixed
     44px circle that only mounts once you scroll, so no load-time audit
     sees it. Ozon paints it with an INLINE `background: var(--white)`,
     i.e. literal #fff, and its chevron with --graphicNeutral: a stark
     white puck floating over the dark page. --white is a raw palette
     entry (white text on brand fills depends on it), so rebind it only
     inside this widget rather than globally. */
  [data-widget="homeButton"] {
    --white: var(--d-surface) !important;
  }

  /* cookie bubble + any leftover notification surface */
  [data-widget="cookieBubble"] {
    background-color: var(--d-surface) !important;
    color: var(--d-text) !important;
    border-color: var(--d-border) !important;
  }

  /* HEADER / FOOTER / SEARCH-BAR ACTION ICONS — account, orders,
     favourites, cart, camera, magnifier, social glyphs. All are
     `fill: currentColor` off --graphicPrimary / --graphicSecondary /
     --graphicPrimaryInverted, all remapped at :root, so they read on
     the dark header without a per-widget lift. The lift that used to
     sit here also dimmed the magnifier on the brand-blue search CTA
     (natively --graphicPrimaryInverted white) to muted grey. */

  /* ============================================================
     COMPONENTS THAT HARDCODE COLOUR INSTEAD OF USING THE TOKENS.
     Each was found by the dark-on-dark scan AFTER the token remap,
     i.e. these are the genuine leftovers the tokens cannot reach.
     ============================================================ */

  /* PDP aspect labels ("Цвет:", "Оперативная память:") — a literal
     `color: rgba(0,26,51,.6)` on the label span, ~1.2:1 on dark, so the
     label vanished and only its value remained. */
  [data-widget="webAspects"] span span {
    color: var(--d-text-3) !important;
  }

  /* Carousel shelf headings ("Покупают вместе", "Рекомендуем также")
     are LINKS, and the link component pins `color: #070707` on its
     primary variant. Only the 600Medium heading size is targeted: the
     PDP buybox price is 600Large and tile prices are 500Medium, both of
     which must keep their own (white / green / gradient) colour. */
  [class*="tsHeadline600Medium"] {
    color: var(--d-text) !important;
  }

  /* Spec-rating verdicts ("среднее" / "высокая" / "хороший") ship the
     raw brand blue #005bff (~2.9:1 on the base); lift to our blue. */
  [data-widget="contextQuestionsStatistic"] span {
    color: var(--d-blue) !important;
  }

  /* "Есть дешевле" cross-sell label (data-widget="webBestSeller") ships a
     literal `color: rgba(0,26,51,.6)` navy on its descriptor span — ~1.1:1
     on the base, so on dark the label went fully invisible while only its
     "от 294 ₽" price (token-coloured, already light) remained. The navy is a
     hardcoded literal the tokens never reach; lift the widget's text to the
     muted scale so the label reads (the price stays legible muted grey, in
     keeping with this compact secondary cross-sell). */
  [data-widget="webBestSeller"] span {
    color: var(--d-text-3) !important;
  }

  /* Carousel next/prev arrows float over the shelf as a disc painted
     with --ozTextPrimaryNegative ("white text on inverse") used as a
     BACKGROUND, with --ozTextPrimary as the chevron. Once both are
     remapped light the disc is a near-white circle carrying an
     invisible light chevron. `aria-label` is the stable hook (Ozon
     ships it in English). The disabled arrow keeps its faint ground. */
  button[aria-label="Next slide"] > span,
  button[aria-label="Previous slide"] > span {
    background-color: var(--d-surface) !important;
    color: var(--d-text) !important;
  }
  button[disabled][aria-label="Next slide"] > span,
  button[disabled][aria-label="Previous slide"] > span {
    background-color: rgba(255, 255, 255, 0.05) !important;
    color: var(--d-text-4) !important;
  }

  /* generic SVG icons that inherit currentColor stay readable */
  svg {
    color: inherit;
  }

  /* legacy <font color="#000000"> tags (used for some spec-rating
     labels like "Среднее"/"Высокая") set colour via an HTML attribute
     that no class rule can reach — override the element directly */
  font,
  [color] {
    color: var(--d-text-2) !important;
  }
}
